FlatFileItemReader<Employee> reader = new FlatFileItemReader<>();
reader.setResource(new ClassPathResource("employees.csv"));
reader.setLineMapper(new DefaultLineMapper<Employee>() {{
    setLineTokenizer(new DelimitedLineTokenizer() {{
        setNames("empId", "empName", "email", "jobLocation");
    }});
    setFieldSetMapper(new BeanWrapperFieldSetMapper<Employee>() {{
        setTargetType(Employee.class);
    }});
}});

@Bean
@StepScope
public StaxEventItemReader<Employee> staxEventEmployeeItemReader(
        @Value("#{jobParameters['inputFile']}") FileSystemResource fileResource) {
    StaxEventItemReader<Employee> reader = new StaxEventItemReader<>();
    reader.setResource(fileResource);
    reader.setFragmentRootElementName("employee");
    reader.setUnmarshaller(new Jaxb2Marshaller() {{
        setClassesToBeBound(Employee.class);
    }});
    return reader;
}

@Bean
public JsonItemReader<Employee> jsonEmployeeItemReader() {
    JsonItemReader<Employee> reader = new JsonItemReader<>();
    reader.setResource(new ClassPathResource("employees.json"));
    reader.setJsonObjectReader(new JacksonJsonObjectReader<>(Employee.class));
    return reader;
}

@Bean
public JdbcCursorItemReader<Employee> jdbcEmployeeItemReader(DataSource dataSource) {
    JdbcCursorItemReader<Employee> reader = new JdbcCursorItemReader<>();
    reader.setDataSource(dataSource);
    reader.setSql("SELECT * FROM employee");
    reader.setRowMapper(new BeanPropertyRowMapper<Employee>() {{
        setMappedClass(Employee.class);
    }});
    return reader;
}

